<section class="phero"><div class="phero-bg"><img src="/assets/img/photos/paperwork.webp" srcset="/assets/img/photos/paperwork-640.webp 640w, /assets/img/photos/paperwork.webp 960w" sizes="100vw" width="960" height="641" alt="" fetchpriority="high" decoding="async" data-parallax="0.15"></div><div class="wrap phero-in"><nav class="crumbs" aria-label="Breadcrumb"><a href="/">Home</a><i aria-hidden="true">/</i><a href="/policy-math-tools/">Free tools</a><i aria-hidden="true">/</i><span aria-current="page">RCV vs. ACV Holdback Calculator</span></nav><p class="kicker">Free calculator</p><h1>RCV vs. ACV Calculator for Depreciation Holdback</h1><p class="lede">Replacement-cost policies usually pay in two parts: actual cash value now and recoverable depreciation after repairs. Enter your damaged items to see how the money splits.</p></div></section>
<section class="sec tool-sec"><div class="wrap"><div class="rv">
<div class="tool tool-wide" data-tool="dep">
  <div class="tool-head"><span>RCV vs. ACV holdback calculator</span><i>Add as many items as you need</i></div>
  <div class="tool-body">
    <div class="tool-in">
      <div class="table-wrap items-table"><table><thead><tr><th>Item</th><th>Replacement cost ($)</th><th>Age (yrs)</th><th>Life (yrs)</th><th>ACV</th><th><span class="sr-only">Remove</span></th></tr></thead><tbody>
      <tr><td><input name="item" value="Laminated shingle roof" aria-label="Item"></td><td><input name="rcv" inputmode="decimal" value="21400" aria-label="Replacement cost"></td><td><input name="age" inputmode="decimal" value="11" aria-label="Age in years"></td><td><input name="life" inputmode="decimal" value="30" aria-label="Expected life in years"></td><td class="mono" data-o="row">$0</td><td><button type="button" class="x" aria-label="Remove row">×</button></td></tr><tr><td><input name="item" value="Vinyl siding — north and west walls" aria-label="Item"></td><td><input name="rcv" inputmode="decimal" value="6800" aria-label="Replacement cost"></td><td><input name="age" inputmode="decimal" value="14" aria-label="Age in years"></td><td><input name="life" inputmode="decimal" value="40" aria-label="Expected life in years"></td><td class="mono" data-o="row">$0</td><td><button type="button" class="x" aria-label="Remove row">×</button></td></tr><tr><td><input name="item" value="Interior paint — great room" aria-label="Item"></td><td><input name="rcv" inputmode="decimal" value="2100" aria-label="Replacement cost"></td><td><input name="age" inputmode="decimal" value="5" aria-label="Age in years"></td><td><input name="life" inputmode="decimal" value="10" aria-label="Expected life in years"></td><td class="mono" data-o="row">$0</td><td><button type="button" class="x" aria-label="Remove row">×</button></td></tr>
      </tbody></table></div>
